// GENERATED preamble — every unit in the estate starts here, identically.
// Rejects an envelope whose MAJOR version this unit does not implement, rather than
// half-processing a shape it does not understand.
const SUPPORTED_MAJOR = 1;
const raw = $json.envelope ?? $json;
const v = String(raw.envelope_version ?? '0.0.0');
if (Number(v.split('.')[0]) !== SUPPORTED_MAJOR) {
  throw new Error('VALIDATION_FAILED: envelope_version ' + v + ' is not supported by media.captions.generate@1.0.0 (needs ' + SUPPORTED_MAJOR + '.x)');
}
for (const f of ['trace_id', 'tenant_id', 'idempotency_key']) {
  if (!raw[f]) throw new Error('VALIDATION_FAILED: envelope.' + f + ' is required');
}
if (raw.deadline_at && Date.parse(raw.deadline_at) < Date.now()) {
  // Fail fast rather than start work that cannot finish in time.
  throw new Error('TIMEOUT: deadline_at ' + raw.deadline_at + ' already passed before media.captions.generate started');
}
return [{ json: {
  ...raw,
  span_id: 'spn_' + Math.random().toString(36).slice(2, 10),
  parent_span_id: raw.span_id ?? null,
  policy: raw.policy ?? {},
  budget: raw.budget ?? {},
  provenance: raw.provenance ?? [],
  _started_at: Date.now(),
  _capability: "media.captions.generate",
  _capability_version: "1.0.0"
} }];

// GENERATED telemetry — span_start.
const e = $json;
return [{ json: { ...e, _telemetry: {
  event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
  trace_id: e.trace_id, span_id: e.span_id, parent_span_id: e.parent_span_id,
  tenant_id: e.tenant_id, brand_id: e.brand_id ?? null, vertical: e.vertical ?? null,
  capability: "media.captions.generate", capability_version: "1.0.0",
  layer: "terminal", stage: e.stage ?? null,
  event: 'span_start', at: new Date().toISOString()
} } }];

// Cue grouping rules that survive contact with real phones: never more than 3 words on a
// line for vertical video, never longer than 1.6s on screen, never split a number from its unit.
const p = $json.payload;
const words = p.words || [];
const maxWords = p.max_words_per_cue || (p.aspect_ratio === '9:16' ? 3 : 6);
const maxDur = p.max_cue_duration_s || 1.6;
const cues = [];
let buf = [];
const flush = () => { if (!buf.length) return; cues.push({ text: buf.map(w => w.word).join(' '), start_s: buf[0].start_s, end_s: buf[buf.length - 1].end_s }); buf = []; };
for (const w of words) {
  buf.push(w);
  const dur = buf[buf.length - 1].end_s - buf[0].start_s;
  if (buf.length >= maxWords || dur >= maxDur) flush();
}
flush();
return [{ json: {
  cues,
  cue_count: cues.length,
  style: { position: p.aspect_ratio === '9:16' ? 'lower_third_safe' : 'bottom_center', weight: 'bold', stroke: true, background: 'semi_opaque', max_width_pct: 80 },
  srt: cues.map((c, i) => `${i + 1}\n${new Date(c.start_s * 1000).toISOString().substr(11, 12).replace('.', ',')} --> ${new Date(c.end_s * 1000).toISOString().substr(11, 12).replace('.', ',')}\n${c.text}\n`).join('\n')
} }];

// GENERATED epilogue — appends exactly one provenance entry and closes the span.
// Provenance is append-only; nothing in the estate is permitted to rewrite an earlier entry.
const e = $('Envelope In').first().json;
const out = $json;
const duration = Date.now() - (e._started_at ?? Date.now());
const entry = {
  capability: "media.captions.generate",
  version: "1.0.0",
  at: new Date().toISOString(),
  duration_ms: duration,
  model: out._model ?? null,
  provider: out._provider ?? null,
  cost_minor_units: out._cost_minor_units ?? 0,
  inputs_hash: e.idempotency_key,
  decision_id: out.decision?.decision_id ?? null
};
return [{ json: {
  ...out,
  _envelope: {
    ...e,
    span_id: e.parent_span_id,
    provenance: [...(e.provenance ?? []), entry],
    budget: { ...(e.budget ?? {}), spent_minor_units: (e.budget?.spent_minor_units ?? 0) + (entry.cost_minor_units ?? 0) }
  },
  _telemetry: {
    event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
    trace_id: e.trace_id, span_id: e.span_id, tenant_id: e.tenant_id,
    capability: "media.captions.generate", capability_version: "1.0.0",
    layer: "terminal", event: 'span_end', status: out.error ? 'error' : 'ok',
    duration_ms: duration, cost_minor_units: entry.cost_minor_units,
    error_code: out.error?.code ?? null, at: new Date().toISOString()
  }
} }];

